package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Beta.Threads.New(
		context.TODO(),
		openai.BetaThreadNewParams{
			Messages: []openai.CreateMessageRequest{openai.CreateMessageRequest{Role: openai.CreateMessageRequestRoleUser, Content: "string", Attachments: []openai.CreateMessageRequestAttachmentsItem{openai.CreateMessageRequestAttachmentsItem{FileID: "string", Tools: []openai.CreateMessageRequestAttachmentsItemToolsItem{openai.AssistantToolsCode{Type: "code_interpreter"}}}}, Metadata: map[string]string{"key": "string"}}},
			ToolResources: openai.CreateThreadRequestToolResources{CodeInterpreter: openai.CreateThreadRequestToolResourcesCodeInterpreter{FileIds: []string{"string"}}, FileSearch: nil},
			Metadata: map[string]string{"key": "string"},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
